signature.example_good:
// Option A: Let it propagate (caller handles)
async function getUser(id: string) {
  return await db.users.get(id)
}

// Option B: Transform the error (adds value)
async function getUser(id: string) {
  try {
    return await db.users.get(id)
  } catch (error) {
    throw new UserFetchError(id, { cause: error })
  }
}

