example.code:
// utils/userHelpers.ts

/**
 * Formats the user's full name.
 * @param firstName - The first name of the user
 * @param lastName - The last name of the user
 * @returns The full name as a string
 */
export function formatUserFullName(firstName: string, lastName: string): string {
  // Combine first and last name with a space
  const fullName: string = `${firstName} ${lastName}`
  // Return the formatted full name
  return fullName
}

/**
 * Checks if a user is an admin.
 * @param user - The user object to check
 * @returns True if the user is an admin, false otherwise
 */
export function checkIfUserIsAdmin(user: User): boolean {
  // Check the role property
  const isAdmin: boolean = user.role === 'admin'
  // Return the result
  return isAdmin
}

/**
 * Fetches user data from the API.
 * @param userId - The ID of the user to fetch
 * @returns The user data
 */
export async function fetchUserDataFromApi(userId: string): Promise<UserData> {
  try {
    // Make the API call
    const response: Response = await fetch(`/api/users/${userId}`)
    // Parse the response
    const data: UserData = await response.json()
    // Return the data
    return data
  } catch (error) {
    // Log the error
    console.error('Error fetching user data:', error)
    // Re-throw the error
    throw error
  }
}

