// features/settings/ToggleSetting.tsx -- ONE file
export function ToggleSetting({ label, value, onChange }: {
  label: string
  value: boolean
  onChange: (v: boolean) => void
}) {
  return (
    <label className="flex items-center gap-2">
      <input type="checkbox" checked={value} onChange={e => onChange(e.target.checked)} />
      {label}
    </label>
  )
}

example.code:
// services/billing.ts
import { api } from '@/shared/api'
import { BillingError } from '@/shared/errors'

export async function upgradePlan(tenantId: string, plan: PlanTier) {
  const tenant = await api.get<Tenant>(`/tenants/${tenantId}`)

  if (tenant.plan === plan) return tenant
  if (!canUpgrade(tenant.plan, plan)) {
    throw new BillingError('downgrade-not-allowed', { current: tenant.plan, requested: plan })
  }

  return api.patch<Tenant>(`/tenants/${tenantId}`, { plan })
}

const PLAN_ORDER: PlanTier[] = ['free', 'starter', 'pro', 'enterprise']
const canUpgrade = (from: PlanTier, to: PlanTier) =>
  PLAN_ORDER.indexOf(to) > PLAN_ORDER.indexOf(from)
